async function openWorld(){data=await api();({state,art,lines,definition}=data);model=createWorldModel(definition);({ROOMS,GATES,mapPieces,ITEMS,LOCKS,friendDone,nextHint,nextGoal,goalTarget,MAP_GATES,targetStatus,availableExits}=model);definition=model.definition;$('#world').classList.toggle('small-world',!!definition.early);$('.place small').textContent=definition.early?data.name+"’s World":'THE CASTLE KINGDOM';document.title=data.name+"’s World";await warmVoices();$('#adult').hidden=true;$('#loading').hidden=true;$('#world').hidden=false;renderRoom();}
let gate;async function showGate(){gate=await fetch('/api/book/review/gate').then(r=>r.json());if(gate.unlocked)return openWorld();$('#loading').hidden=true;$('#adult').hidden=false;$('#question').textContent=gate.question;$('#code').textContent=gate.code;}
$('#gate-form').onsubmit=async e=>{e.preventDefault();try{const r=await fetch('/api/book/review/gate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:gate.id,answer:$('#answer').value})}),j=await r.json();if(!r.ok)throw Error(j.error);await openWorld();}catch(e){$('#gate-status').textContent=e.message;await showGate();}};
void openWorld().catch(async e=>{if(e.status===403){try{await showGate();return;}catch(gateError){e=gateError;}}$('#loading').hidden=false;$('#loading').textContent=e.message;});

// Playback warms recorded bytes only. Rendering is a release step, never a child tap.
async function warmVoices(){const priority=['start',nextHint(state),'friend-'+state.room+'-0','on-way','path','found','piece'],urls=values=>values.filter(l=>l?.clip).map(l=>'/book-voice/'+l.clip+'?r=L1');await audio.warm(urls(priority.map(key=>lines?.[key])));void audio.warm(urls(Object.values(lines||{})));}
function feedback(button){button.classList.add('tap-feedback');setTimeout(()=>button.classList.remove('tap-feedback'),180);}
let pictureProgress=0;
function drawPictureChallenge(){
 const sceneKey=challengeGate;if(GATES[sceneKey].scenePuzzle)return mountScenePuzzle({gate:GATES[sceneKey],key:sceneKey,element:$('#challenge'),scene:$('#scene'),background:art.backgrounds[ROOMS[state.room].bg||state.room],unlock,speak,finished:()=>audio.finished(),hint,close:closeChallenge,answer,onError:showError,onLayout:layout});
 const g=GATES[challengeGate],el=$('#challenge');pictureProgress=0;el.hidden=false;
 const playable=['order','count','pattern'].includes(g.kind);
 el.innerHTML=`<button class="close" aria-label="Return to the world">×</button><h2>${esc(g.title)}</h2><p>${esc(g.prompt.replace(/\[\[ɑ\]\]/g,'/o/'))}</p><div class="picture-progress" aria-live="polite"></div><div class="picture-play ${esc(g.kind)}">${playable?Array.from({length:g.count},(_,i)=>`<button data-step="${i}" aria-label="${g.kind==='count'?(g.countVisual||'Pizza'):g.kind==='pattern'?'Empty flower patch':'Step'} ${i+1}" class="${i===0&&g.kind!=='count'?'next-target':''}"><span aria-hidden="true">${g.kind==='count'?countPicture(g):g.kind==='pattern'?'🟫':challengeGate==='mats'?'🔵':'🪨'}</span></button>`).join(''):g.options.map(id=>`<button data-answer="${esc(id)}" aria-label="${esc(id)}"><span aria-hidden="true">${esc(g.pictures[id])}</span></button>`).join('')}</div>${g.kind==='count'?`<div class="pizza-box" aria-label="Collected objects">${definition.episode?'🏮':'📦'}</div>`:challengeGate==='mats'?'<div class="blue-bar" aria-label="Blue pull-up bar">━</div>':g.kind==='pattern'?'<div class="flower-pattern" aria-label="Flower, space, flower, space">🌼　 🌼　</div>':''}<button class="help" aria-label="Hear a hint">💬 ?</button><p class="hint-text" hidden></p>`;
 el.querySelector('.close').onclick=closeChallenge;el.querySelector('.help').onclick=()=>{unlock();hint();};
 if(friend&&geometry.friend){place(friend,{x:geometry.friend.x,y:.985},{w:geometry.friend.w,h:geometry.friend.h});}position=clearHeroSpot(position);place(hero,position,heroSize());
 for(const b of el.querySelectorAll('[data-answer]')){if(g.kind==='picture-word')support(b,b.dataset.answer);}for(const b of el.querySelectorAll('[data-answer]'))b.onclick=()=>{unlock();feedback(b);void answer(b.dataset.answer,b).catch(showError);};
 for(const b of el.querySelectorAll('[data-step]'))b.onclick=()=>{
  unlock();feedback(b);const index=Number(b.dataset.step);if(b.classList.contains('used'))return;
  if(g.kind!=='count'&&index!==pictureProgress){hint();return;}
  pictureProgress++;b.classList.add('used');b.disabled=true;b.classList.remove('next-target');
  if(g.kind==='count'){b.style.visibility='hidden';el.querySelector('.pizza-box').append(Object.assign(document.createElement('span'),{textContent:countPicture(g)}));}
  if(g.kind==='pattern')b.querySelector('span').textContent='🌼';
  el.querySelector('.picture-progress').textContent='● '.repeat(pictureProgress);el.querySelector(`[data-step="${pictureProgress}"]`)?.classList.add('next-target');
  void speak('count-'+pictureProgress);
  if(pictureProgress===g.count){if(challengeGate==='mats'){const img=hero?.querySelector('img');img?.animate([{translate:'0 0'},{translate:'0 -24px'},{translate:'0 0'}],{duration:700});}const key=challengeGate;const completion=audio.finished();void completion.then(()=>{if(challengeGate===key&&!document.hidden)void answer(g.answer,b).catch(showError);});}
 };
}

function clearHeroSpot(preferred){const reservations=[...document.querySelectorAll('.actor:not(.hero),[data-object],.world-toy,.signpost,.hud')].filter(e=>!e.hidden).map(e=>{const r=e.getBoundingClientRect();return {x0:r.x/geometry.W,x1:r.right/geometry.W,y0:r.y/geometry.H,y1:r.bottom/geometry.H};});return worldSpot(preferred,heroSize(),reservations,{floor:Math.max(geometry.floor,.93)});}

function showCollection(){stopWalk();$('#map').hidden=false;$('#map').innerHTML=`<button class="close" aria-label="Return to the world">×</button><h2>Your collection shelf</h2><div class="collection-shelf">${Object.entries(ITEMS).filter(([id,v])=>definition.episode?state.items.includes(id):v.collection).map(([id,v])=>`<div class="${state.items.includes(id)?'collected':'undiscovered'}">${icon(v.icon)}<p>${state.items.includes(id)?esc(v.name):'A hidden discovery'}</p></div>`).join('')}</div><p>${definition.episode?'Your discoveries from every quest stay with you.':'Explore the library, cabin, lighthouse and waterfall after finding the treasure.'}</p><button class="continue">Back to the world</button>`;wireOverlayClose();}
function challengeShell(g,body){const el=$('#challenge');el.hidden=false;el.innerHTML=`<button class="close" aria-label="Return to the world">×</button><h2>${esc(g.title)}</h2><p>${esc(g.kind==='sound'?'Hear the sound. Tap its letter.':g.prompt)}</p>${body}<button class="help">A little hint</button><p class="hint-text" hidden></p>`;el.querySelector('.close').onclick=closeChallenge;el.querySelector('.help').onclick=()=>{unlock();hint();};return el;}
function drawTiles(g){let word=0,letters='';const el=challengeShell(g,'<div class="word-card"></div><div class="tile-slots" aria-live="polite"></div><div class="letter-tiles"></div><button class="undo-letter">Undo</button>');const render=()=>{const target=g.words[word];const card=el.querySelector('.word-card');card.textContent=g.clues?g.clues[word]:(word===0?(g.picture||'')+' ':'')+(g.displayWords?.[word]||target);support(card,target,{showLetters:false});el.querySelector('.tile-slots').textContent=(g.uppercase?letters.toUpperCase():letters)+' _'.repeat(target.length-letters.length);el.querySelector('.letter-tiles').innerHTML=[...target].sort().reverse().map((c,i)=>`<button data-letter="${c}" data-tile="${i}">${g.uppercase?c.toUpperCase():c}</button>`).join('');for(const b of el.querySelectorAll('[data-letter]'))b.onclick=()=>{unlock();feedback(b);let soundFinished;if(lines['sound-'+challengeGate+'-'+b.dataset.letter]?.clip){void speak('sound-'+challengeGate+'-'+b.dataset.letter);soundFinished=audio.finished();}else{voiceTurn++;audio.stop();soundFinished=phonics.letter(b.dataset.letter);if(!hasSound(b.dataset.letter)){const prompt=el.querySelector('p:not(.hint-text)');if(prompt)prompt.hidden=true;const status=el.querySelector('.hint-text');status.hidden=false;status.textContent='Ask a grown-up to say this letter sound.';layout();}}if(b.dataset.letter!==target[letters.length]){const key=challengeGate;void Promise.resolve(soundFinished).then(()=>{if(challengeGate===key)hint();});return;}letters+=b.dataset.letter;if(letters===target){if(++word===g.words.length){const key=challengeGate;void Promise.resolve(soundFinished).then(()=>{if(challengeGate===key)void answer(g.answer,b).catch(showError);});return;}letters='';}render();};};el.querySelector('.undo-letter').onclick=()=>{letters=letters.slice(0,-1);render();};render();}

function drawKick(g){let aim=null,power=null;const el=challengeShell(g,'<div class="kick-goal" aria-label="Goal aiming positions">🥅</div><div class="aim-options">'+['Left','Middle','Right'].map((v,i)=>`<button data-aim="${i}">${v}</button>`).join('')+'</div><div class="power-options">'+['Gentle','Medium','Strong'].map((v,i)=>`<button data-power="${i}">${v}</button>`).join('')+'</div><button class="kick-ball" disabled>⚽ Kick!</button><p class="kick-feedback" aria-live="polite"></p>');for(const kind of ['aim','power'])for(const b of el.querySelectorAll('[data-'+kind+']'))b.onclick=()=>{unlock();feedback(b);if(kind==='aim')aim=+b.dataset.aim;else power=+b.dataset.power;for(const x of el.querySelectorAll('[data-'+kind+']'))x.classList.toggle('chosen',x===b);el.querySelector('.kick-ball').disabled=aim===null||power===null;};el.querySelector('.kick-ball').onclick=async()=>{unlock();const scored=aim===1&&power===1;el.querySelector('.kick-feedback').textContent=scored?'Goal!':'Nearly! Adjust your aim or power and try again.';if(scored)await answer('goal',el.querySelector('.kick-ball'));else {void speak('hint-kick');} };}

function drawSoundChallenge(){const g=GATES[challengeGate],el=challengeShell(g,`<button class="hear-sound" aria-label="Hear the clue sound">🔊</button><div class="answers">${g.options.map(L=>`<button data-answer="${esc(L)}">${esc(L)}</button>`).join('')}</div>`);el.querySelector('.hear-sound').onclick=()=>{unlock();void speak('sound-'+challengeGate+'-'+g.letter);};for(const b of el.querySelectorAll('[data-answer]'))b.onclick=()=>{unlock();void answer(b.dataset.answer,b).catch(showError);};}

function countPicture(g){return definition.episode?({stone:'🪨',flower:'🌼',acorn:'🌰',light:'⭐'})[g.countVisual||'light']:'🍕';}

// Match the rendered narration (24 kHz / 16-bit PCM), rather than opening the
// output device with the coach's legacy 8 kHz / 8-bit sample on the first tap.
function silentWav(){const bytes=new Uint8Array(44+960),v=new DataView(bytes.buffer),word=(at,s)=>[...s].forEach((c,i)=>bytes[at+i]=c.charCodeAt(0));word(0,'RIFF');v.setUint32(4,bytes.length-8,true);word(8,'WAVE');word(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,24000,true);v.setUint32(28,48000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);word(36,'data');v.setUint32(40,960,true);return 'data:audio/wav;base64,'+btoa(String.fromCharCode(...bytes));}

const toyAnimations=new Set();let toyContext=null,toyNodes=new Set();
function stopToys(){for(const a of toyAnimations)a.cancel();toyAnimations.clear();for(const n of toyNodes){try{n.stop();n.disconnect();}catch{}}toyNodes.clear();}
function toySound(kind){if(muted||disposed||document.hidden||globalThis.familyAudio?.blocked)return;try{toyContext??=new (globalThis.AudioContext||globalThis.webkitAudioContext)();void toyContext.resume();const t=toyContext.currentTime,o=toyContext.createOscillator(),g=toyContext.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='drum'?130:kind==='bubbles'?550:220,t);o.frequency.exponentialRampToValueAtTime(kind==='drum'?65:kind==='bubbles'?750:120,t+.12);g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.0001,t+.17);o.connect(g);g.connect(toyContext.destination);toyNodes.add(o);o.onended=()=>{toyNodes.delete(o);o.disconnect();g.disconnect();};o.start();o.stop(t+.18);}catch{}}
function animateToy(el,frames,options){const a=el.animate(frames,{duration:900,easing:'ease-out',...options});toyAnimations.add(a);void a.finished.catch(()=>{}).finally(()=>toyAnimations.delete(a));return a;}
function renderToys(){const drawings={
 tetherball:'<svg viewBox="0 0 120 110" aria-hidden="true"><ellipse cx="58" cy="98" rx="40" ry="6" fill="#668765"/><path d="M58 99V16" stroke="#8b745a" stroke-width="6"/><g class="toy-moving"><path d="M58 18L95 57" stroke="#f5e1b6" stroke-width="3"/><circle cx="96" cy="60" r="14" fill="#edb85b" stroke="#996b35" stroke-width="2"/></g></svg>',
 soccer:'<svg viewBox="0 0 120 110" aria-hidden="true"><path d="M12 59V14H108V59M12 14L23 28H97L108 14M23 28V59M97 28V59M12 59H108" fill="#fcf9ed55" stroke="#eee6d0" stroke-width="4"/><path d="M24 17V56M42 17V56M60 17V56M78 17V56M96 17V56M15 30H105M15 43H105" stroke="#b8b49c"/><g class="toy-moving"><circle cx="60" cy="89" r="13" fill="#fff9eb" stroke="#514e48" stroke-width="2"/><path d="M56 82H65L69 89L63 96L54 92Z" fill="#514e48"/></g></svg>',
 bubbles:'<svg viewBox="0 0 120 110" aria-hidden="true"><path d="M51 94L66 65" stroke="#d5bd8b" stroke-width="6"/><circle cx="70" cy="57" r="16" fill="none" stroke="#eed5aa" stroke-width="5"/><g class="toy-moving" fill="#b9e5e877" stroke="#faf5e6" stroke-width="2"><circle cx="40" cy="40" r="14"/><circle cx="85" cy="25" r="10"/><circle cx="20" cy="66" r="8"/></g></svg>',
 drum:'<svg viewBox="0 0 120 110" aria-hidden="true"><g class="toy-moving"><path d="M24 47V88Q60 109 96 88V47" fill="#bd7d63" stroke="#806147" stroke-width="3"/><path d="M30 55L45 92L60 55L75 92L90 55" fill="none" stroke="#e8cd93" stroke-width="3"/><ellipse cx="60" cy="47" rx="36" ry="14" fill="#eddbb4" stroke="#806147" stroke-width="3"/></g><path d="M12 19L43 39M108 19L77 39" stroke="#e5c48b" stroke-width="5"/></svg>'};
 for(const spec of worldToys(definition)[state.room]||[]){const kind=typeof spec==='string'?spec:spec.kind;if(!drawings[kind])continue;const b=document.createElement('button');b.className='world-toy';b.dataset.toy=kind;b.setAttribute('aria-label',({tetherball:'Whip the tetherball around the pole',soccer:'Shoot at the soccer goal again',bubbles:'Blow more bubbles',drum:'Tap the drum'})[kind]);b.innerHTML=drawings[kind]+'<span class="toy-label">'+({tetherball:'Tap or swipe',soccer:'Shoot again',bubbles:'More bubbles',drum:'Tap the drum'})[kind]+'</span>';let down=null;
  const play=(direction=1)=>{if(disposed||document.hidden||!$('#map').hidden||challengeGate)return;interactionTurn++;stopWalk();voiceTurn++;audio.stop();rewardAudio.stop();phonics.stop();feedback(b);for(const a of b.getAnimations({subtree:true}))a.cancel();toySound(kind);const moving=b.querySelector('.toy-moving');
   if(kind==='tetherball')animateToy(moving,[{transform:'rotate(0deg) scaleX(1)'},{transform:'rotate('+direction*35+'deg) scaleX(-.7)',offset:.18},{transform:'rotate('+direction*-25+'deg) scaleX(1)',offset:.38},{transform:'rotate('+direction*15+'deg) scaleX(-.5)',offset:.58},{transform:'rotate('+direction*-8+'deg) scaleX(1)',offset:.78},{transform:'rotate(0deg) scaleX(1)'}],{duration:1800});
   if(kind==='soccer')animateToy(moving,[{transform:'translate(0,0) scale(1)'},{transform:'translate(0,-48px) scale(.55)',offset:.45},{transform:'translate(0,-40px) scale(.55)',offset:.65},{transform:'translate(0,0) scale(1)'}],{duration:1000});
   if(kind==='bubbles')animateToy(moving,[{transform:'translateY(5px) scale(.6)',opacity:.4},{transform:'translateY(-12px) scale(1)',opacity:1,offset:.45},{transform:'translateY(-35px) scale(1.15)',opacity:0}],{duration:1500});
   if(kind==='drum')animateToy(moving,[{transform:'scaleY(1)'},{transform:'scaleY(.88)',offset:.2},{transform:'scaleY(1)'}],{duration:250});
  };
  b.onpointerdown=e=>{down={x:e.clientX,y:e.clientY};b.setPointerCapture(e.pointerId);};b.onpointerup=e=>{if(down&&Math.hypot(e.clientX-down.x,e.clientY-down.y)>12){play(e.clientX<down.x?-1:1);b.dataset.dragged='1';}down=null;};b.onpointercancel=()=>{down=null;};b.onclick=()=>{if(b.dataset.dragged){delete b.dataset.dragged;return;}play();};$('#actors').append(b);
 }
}
